def _bool_mask(df: pd.DataFrame, column: str) -> pd.Series:
    if column not in df.columns:
        return pd.Series(False, index=df.index, dtype=bool)
    return df[column].fillna(False).astype(bool)


def _ensure_frame_columns(df: pd.DataFrame, column_names: Sequence[str]) -> pd.DataFrame:
    out = df.copy()
    for column_name in column_names:
        if column_name not in out.columns:
            out[column_name] = np.nan
    return out


def _hour_as_string(series: pd.Series) -> pd.Series:
    return pd.to_numeric(series, errors="coerce").round().astype("Int64").astype("string").fillna("NA")


def _weekday_as_string(series: pd.Series) -> pd.Series:
    return pd.to_numeric(series, errors="coerce").round().astype("Int64").astype("string").fillna("NA")


def _augment_pocket_features(df: pd.DataFrame) -> pd.DataFrame:
    augmented = df.copy()
    alias_map = {
        "xgb_p_long": "p_long",
        "xgb_p_short": "p_short",
        "xgb_p_flat": "p_flat",
        "xgb_p_hat": "p_hat",
        "xgb_uncertainty_score": "uncertainty_score",
        "xgb_margin_top1_top2": "margin",
        "entry_p_long": "p_long",
        "entry_p_short": "p_short",
        "entry_p_flat": "p_flat",
        "entry_p_hat": "p_hat",
        "entry_uncertainty_score": "uncertainty_score",
        "entry_margin_top1_top2": "margin",
        "runtime_side_prob_v1": "p_hat",
    }
    for target_col, source_col in alias_map.items():
        if target_col not in augmented.columns and source_col in augmented.columns:
            augmented[target_col] = augmented[source_col]
    if "xgb_entropy" not in augmented.columns and "uncertainty_score" in augmented.columns:
        augmented["xgb_entropy"] = augmented["uncertainty_score"]
    if "entry_entropy" not in augmented.columns and "uncertainty_score" in augmented.columns:
        augmented["entry_entropy"] = augmented["uncertainty_score"]
    if "bad_path_prob" not in augmented.columns:
        if "path_quality_pred" in augmented.columns:
            path_quality = pd.to_numeric(augmented["path_quality_pred"], errors="coerce").fillna(0.0)
            augmented["bad_path_prob"] = (1.0 - path_quality).clip(lower=0.0)
        else:
            augmented["bad_path_prob"] = 0.0
    if "runtime_override_active_v1" not in augmented.columns:
        augmented["runtime_override_active_v1"] = False
    if "threshold_gate_bypassed" not in augmented.columns:
        augmented["threshold_gate_bypassed"] = False
    if "tradable_gate_bypassed" not in augmented.columns:
        augmented["tradable_gate_bypassed"] = False
    if "runtime_flat_edge_v1" not in augmented.columns and {"p_flat", "p_long", "p_short"}.issubset(augmented.columns):
        p_flat = pd.to_numeric(augmented["p_flat"], errors="coerce").fillna(0.0)
        p_long = pd.to_numeric(augmented["p_long"], errors="coerce").fillna(0.0)
        p_short = pd.to_numeric(augmented["p_short"], errors="coerce").fillna(0.0)
        augmented["runtime_flat_edge_v1"] = p_flat - pd.concat([p_long, p_short], axis=1).max(axis=1)
    return augmented


def _safe_bool_mean(series: pd.Series) -> float:
    if len(series) == 0:
        return 0.0
    return float(series.fillna(False).astype(bool).mean())


def _safe_float_mean(series: pd.Series) -> float:
    if len(series) == 0:
        return 0.0
    return float(pd.to_numeric(series, errors="coerce").mean())


def _coerce_float_or_none(value: Any) -> float | None:
    numeric = pd.to_numeric(pd.Series([value]), errors="coerce").iloc[0]
    if pd.isna(numeric):
        return None
    return float(numeric)


def _coerce_int(value: Any) -> int:
    numeric = pd.to_numeric(pd.Series([value]), errors="coerce").iloc[0]
    if pd.isna(numeric):
        return 0
    return int(numeric)


def _load_json_object_v1(path: Path) -> Dict[str, Any]:
    with path.open("r", encoding="utf-8") as handle:
        payload = json.load(handle)
    if not isinstance(payload, dict):
        raise RuntimeError(f"[SHADOW_META_V1] expected object JSON in {path}")
    return payload


def _build_entry_rl_observability_v1(
    *,
    reports_root: Path,
    as_of_decision_moment_ledger_v1_df: pd.DataFrame,
    policy_action_supervision_join_df: pd.DataFrame,
    entry_anchor_raw_state_df: pd.DataFrame,
    entry_skipability_raw_state_df: pd.DataFrame,
    entry_direct_policy_composite_v1_df: pd.DataFrame,
    entry_wait_lifecycle_view_v1_df: pd.DataFrame,
    entry_actual_take_terminal_outcome_view_v1_df: pd.DataFrame,
    hindsight_export_df: pd.DataFrame,
) -> Dict[str, Any]:
    skipability_pressure_path = reports_root / "truth_entry_skipability_pressure_v1.json"
    market_opportunity_path = reports_root / "truth_continuous_market_opportunity_v1.json"
    if not skipability_pressure_path.exists():
        raise RuntimeError(
            "[ALL_TRADE_REVIEW_LEDGER] ENTRY_RL_OBSERVABILITY_V1 requires truth_entry_skipability_pressure_v1.json"
        )
    if not market_opportunity_path.exists():
        raise RuntimeError(
            "[ALL_TRADE_REVIEW_LEDGER] ENTRY_RL_OBSERVABILITY_V1 requires truth_continuous_market_opportunity_v1.json"
        )
    payload = _build_entry_rl_observability_payload_from_extension(
        direct_df=entry_direct_policy_composite_v1_df,
        asof_df=as_of_decision_moment_ledger_v1_df,
        skip_raw_df=entry_skipability_raw_state_df,
        entry_anchor_raw_df=entry_anchor_raw_state_df,
        supervision_df=policy_action_supervision_join_df,
        wait_lifecycle_df=entry_wait_lifecycle_view_v1_df,
        actual_take_terminal_df=entry_actual_take_terminal_outcome_view_v1_df,
        hindsight_export_df=hindsight_export_df,
        skipability_pressure_summary=_load_json_object_v1(skipability_pressure_path),
        market_opportunity_summary=_load_json_object_v1(market_opportunity_path),
        review_dir=reports_root / _ALL_TRADE_REVIEW_LEDGER_NAME,
    )
    payload["entry_rl_observability_manifest_v1"] = {
        **payload["entry_rl_observability_manifest_v1"],
        "mode_v1": "CANONICAL_BASE_LEDGER",
        "review_dir_v1": str(reports_root / _ALL_TRADE_REVIEW_LEDGER_NAME),
    }
    payload["entry_rl_observability_summary_v1"] = {
        **payload["entry_rl_observability_summary_v1"],
        "review_dir_v1": str(reports_root / _ALL_TRADE_REVIEW_LEDGER_NAME),
    }
    return payload


