def _cast_closed_trade_ledger_types(df: pd.DataFrame, schema_rows: Sequence[Dict[str, Any]]) -> pd.DataFrame:
    out = df.copy()
    for row in schema_rows:
        field_name = str(row["field_name"])
        if field_name not in out.columns:
            continue
        dtype = str(row["dtype"])
        if dtype == "string":
            out[field_name] = out[field_name].astype("string")
        elif dtype == "float64":
            out[field_name] = pd.to_numeric(out[field_name], errors="coerce").astype("float64")
        elif dtype == "Int64":
            out[field_name] = pd.to_numeric(out[field_name], errors="coerce").astype("Int64")
        elif dtype == "boolean":
            out[field_name] = out[field_name].astype("boolean")
    return out


