def _build_decision_moment_teacher_bridge_from_review_surface(
    review_surface_df: pd.DataFrame,
    *,
    control_date: date,
) -> Dict[str, Any]:
    bridge_schema_rows = _decision_moment_teacher_bridge_schema()
    bridge_field_names = [str(row["field_name"]) for row in bridge_schema_rows]
    contract_value = f"{_ALL_TRADE_REVIEW_DECISION_MOMENT_BRIDGE_CONTRACT}|{_ALL_TRADE_REVIEW_DECISION_MOMENT_BRIDGE_MODE}"

    def _extract_reason(full_reason: Any, prefix: str) -> str:
        text = _scalar_string(full_reason)
        if text == _LEDGER_NOT_AVAILABLE:
            return _LEDGER_NOT_AVAILABLE
        for part in text.split(";"):
            part = part.strip()
            if part.startswith(prefix):
                value = part[len(prefix):].strip()
                return value if value else _LEDGER_NOT_AVAILABLE
        return _LEDGER_NOT_AVAILABLE

    def _nonmissing_string(value: Any) -> bool:
        text = _scalar_string(value)
        return text not in {"", _LEDGER_NOT_AVAILABLE, "<NA>", "nan", "NaT"}

    def _coalesce_numeric(mapping: Dict[str, Any], keys: Sequence[str]) -> float:
        for key in keys:
            value = pd.to_numeric(pd.Series([mapping.get(key)]), errors="coerce").iloc[0]
            if pd.notna(value):
                return float(value)
        return float("nan")

    def _coalesce_bool(mapping: Dict[str, Any], keys: Sequence[str]) -> bool | None:
        for key in keys:
            value = mapping.get(key)
            if _scalar_is_missing(value):
                continue
            if isinstance(value, str):
                lowered = value.strip().lower()
                if lowered in {"true", "1", "yes"}:
                    return True
                if lowered in {"false", "0", "no"}:
                    return False
            return bool(value)
        return None

    def _fmt_num(value: Any) -> str:
        numeric = pd.to_numeric(pd.Series([value]), errors="coerce").iloc[0]
        if pd.isna(numeric):
            return "NA"
        return f"{float(numeric):.6f}"

    def _string_counts(series: pd.Series) -> Dict[str, int]:
        text = series.astype("string").fillna("<NA>")
        counts = text.value_counts(dropna=False).to_dict()
        return {str(key): int(value) for key, value in counts.items()}

    def _bool_from_mapping(mapping: Dict[str, Any] | None, key: str) -> bool:
        if not mapping:
            return False
        value = mapping.get(key)
        if _scalar_is_missing(value):
            return False
        if isinstance(value, str):
            lowered = value.strip().lower()
            if lowered in {"true", "1", "yes"}:
                return True
            if lowered in {"false", "0", "no"}:
                return False
        return bool(value)

    def _classify_entry_hierarchy(
        mapping: Dict[str, Any],
        *,
        entry_action: str,
        trade_bucket: str,
        entry_bucket: str,
        skip_value: float,
        peak_mfe: float,
        mae_bps: float,
    ) -> Dict[str, Any]:
        trade_outcome_class = _scalar_string(mapping.get("trade_outcome_class"))
        meaningful_thr = _coalesce_numeric(mapping, ["meaningful_mfe_threshold_bps"])
        first_meaningful_idx = _coalesce_numeric(mapping, ["first_meaningful_mfe_bar_index"])
        adverse_first = bool(_coalesce_bool(mapping, ["adverse_first"]) is True)

        timing_review = "ENTRY_TIMING_UNRESOLVED"
        reason_family = "ENTRY_REASON_UNRESOLVED"
        reason_code = "INSUFFICIENT_SIGNAL_SUPPORT"
        wait_to_reduce_mae = False

        has_meaningful_mfe = bool(np.isfinite(first_meaningful_idx))
        large_mae_before_mfe = bool(
            adverse_first
            and has_meaningful_mfe
            and np.isfinite(mae_bps)
            and np.isfinite(meaningful_thr)
            and float(mae_bps) >= float(meaningful_thr)
        )

        if entry_action == "SKIP_ENTRY":
            reason_family = "BAD_TRADE_QUALITY"
            if trade_outcome_class == "never_mfe":
                reason_code = "NEVER_MFE"
            elif not has_meaningful_mfe:
                reason_code = "NO_MEANINGFUL_MFE"
            elif large_mae_before_mfe:
                reason_code = "LARGE_MAE_BEFORE_MEANINGFUL_MFE"
            elif adverse_first:
                reason_code = "ADVERSE_FIRST_BEFORE_MFE"
        elif entry_action == "TAKE_ENTRY":
            if large_mae_before_mfe:
                timing_review = "ENTER_TOO_EARLY"
                reason_family = "ENTRY_TIMING"
                reason_code = "WAIT_TO_REDUCE_MAE"
                wait_to_reduce_mae = True
            elif entry_bucket == "entry_looked_good_but_failed":
                reason_family = "LOOKED_GOOD_THEN_FAILED"
                reason_code = "LOOKED_GOOD_THEN_FAILED"
            elif entry_bucket == "entry_good_but_fragile":
                reason_family = "ENTRY_PATH_FRAGILE"
                reason_code = "ADVERSE_FIRST_BEFORE_MFE" if adverse_first else "INSUFFICIENT_SIGNAL_SUPPORT"
            else:
                timing_review = "ENTER_NOW_OK"
                reason_family = "ENTRY_TIMING"
                reason_code = "ENTER_NOW_OK"
        else:
            if entry_bucket == "entry_looked_good_but_failed":
                reason_family = "LOOKED_GOOD_THEN_FAILED"
                reason_code = "LOOKED_GOOD_THEN_FAILED"
            elif entry_bucket == "entry_good_but_fragile":
                reason_family = "ENTRY_PATH_FRAGILE"
                reason_code = "ADVERSE_FIRST_BEFORE_MFE" if adverse_first else "INSUFFICIENT_SIGNAL_SUPPORT"

        support = (
            f"entry_action={entry_action};entry_bucket={entry_bucket};trade_bucket={trade_bucket};"
            f"trade_outcome_class={trade_outcome_class};adverse_first={str(adverse_first).upper()};"
            f"first_meaningful_mfe_bar_index={_fmt_num(first_meaningful_idx)};"
            f"meaningful_mfe_threshold_bps={_fmt_num(meaningful_thr)};"
            f"mae_bps={_fmt_num(mae_bps)};peak_mfe_bps={_fmt_num(peak_mfe)};"
            f"skip_trade_avoided_loss_bps={_fmt_num(skip_value)}"
        )
        return {
            "hindsight_teacher_hierarchy_domain_v1": "ENTRY",
            "hindsight_teacher_hierarchy_action_family_v1": entry_action,
            "hindsight_teacher_hierarchy_reason_family_v1": reason_family,
            "hindsight_teacher_hierarchy_reason_code_v1": reason_code,
            "hindsight_teacher_hierarchy_support_v1": support,
            "hindsight_teacher_hierarchy_path_v1": f"ENTRY / {entry_action} / {reason_family} / {reason_code}",
            "hindsight_entry_timing_review_v1": timing_review,
            "hindsight_entry_reason_family_v1": reason_family,
            "hindsight_entry_reason_code_v1": reason_code,
            "hindsight_entry_timing_support_v1": support,
            "hindsight_wait_to_reduce_mae_v1": wait_to_reduce_mae,
            "hindsight_management_reason_family_v1": pd.NA,
            "hindsight_management_reason_code_v1": pd.NA,
            "hindsight_management_reason_support_v1": pd.NA,
            "hindsight_profit_protection_failure_v1": pd.NA,
            "hindsight_left_value_on_table_v1": pd.NA,
            "hindsight_valid_exit_reason_v1": pd.NA,
        }

    def _resolve_entry_action_refined(
        *,
        entry_action: str,
        entry_hierarchy: Dict[str, Any],
        confirmation_anchor: bool = False,
    ) -> str:
        if confirmation_anchor:
            return "TAKE_ENTRY_NOW"

        reason_family = _scalar_string(entry_hierarchy.get("hindsight_entry_reason_family_v1"))
        reason_code = _scalar_string(entry_hierarchy.get("hindsight_entry_reason_code_v1"))
        timing_review = _scalar_string(entry_hierarchy.get("hindsight_entry_timing_review_v1"))

        if entry_action == "SKIP_ENTRY":
            return "SKIP_ENTRY"
        if entry_action == "TAKE_ENTRY":
            if reason_family == "ENTRY_TIMING" and timing_review == "ENTER_NOW_OK":
                return "TAKE_ENTRY_NOW"
            if reason_family == "ENTRY_TIMING" and reason_code == "WAIT_TO_REDUCE_MAE":
                return "WAIT_FOR_CONFIRMATION_ENTRY"
            return "ENTRY_ACTION_UNRESOLVED"
        return "ENTRY_ACTION_UNRESOLVED"

    def _localize_confirmation_entry(
        mapping: Dict[str, Any],
        *,
        refined_action: str,
    ) -> Dict[str, Any]:
        if refined_action != "WAIT_FOR_CONFIRMATION_ENTRY":
            return {
                "hindsight_confirmation_entry_ts_utc_v1": _LEDGER_NOT_AVAILABLE,
                "hindsight_confirmation_entry_localizable_v1": pd.NA,
                "hindsight_confirmation_entry_reason_v1": _LEDGER_NOT_AVAILABLE,
                "hindsight_confirmation_entry_support_v1": _LEDGER_NOT_AVAILABLE,
                "hindsight_confirmation_entry_wait_bars_v1": pd.NA,
                "hindsight_confirmation_entry_wait_minutes_v1": pd.NA,
            }

        adverse_first = bool(_coalesce_bool(mapping, ["adverse_first"]) is True)
        open_ts_raw = pd.to_datetime(pd.Series([mapping.get("open_ts_utc")]), utc=True, errors="coerce").iloc[0]
        close_ts_raw = pd.to_datetime(pd.Series([mapping.get("close_ts_utc")]), utc=True, errors="coerce").iloc[0]
        first_meaningful_idx = _coalesce_numeric(mapping, ["first_meaningful_mfe_bar_index"])
        bars_held_exit_state = _coalesce_numeric(mapping, ["bars_held_exit_state"])

        close_minus_open_minutes = float("nan")
        if pd.notna(open_ts_raw) and pd.notna(close_ts_raw):
            close_minus_open_minutes = float((close_ts_raw - open_ts_raw).total_seconds() / 60.0)

        minute_cadence_pass = bool(
            pd.notna(open_ts_raw)
            and pd.notna(close_ts_raw)
            and np.isfinite(close_minus_open_minutes)
            and np.isfinite(bars_held_exit_state)
            and abs(close_minus_open_minutes - float(bars_held_exit_state)) <= 1e-6
        )
        first_meaningful_idx_pass = bool(
            adverse_first
            and np.isfinite(first_meaningful_idx)
            and float(first_meaningful_idx) > 0.0
            and np.isfinite(bars_held_exit_state)
            and float(first_meaningful_idx) <= float(bars_held_exit_state)
        )

        confirmation_ts_raw = pd.NaT
        if pd.notna(open_ts_raw) and first_meaningful_idx_pass:
            confirmation_ts_raw = open_ts_raw + pd.Timedelta(minutes=float(first_meaningful_idx))
        within_trade_window = bool(
            pd.notna(confirmation_ts_raw)
            and pd.notna(open_ts_raw)
            and pd.notna(close_ts_raw)
            and confirmation_ts_raw > open_ts_raw
            and confirmation_ts_raw < close_ts_raw
        )

        confirmation_support = (
            f"refined_action={refined_action};adverse_first={str(adverse_first).upper()};"
            f"first_meaningful_mfe_bar_index={_fmt_num(first_meaningful_idx)};"
            f"bars_held_exit_state={_fmt_num(bars_held_exit_state)};"
            f"open_ts_utc={_scalar_iso_utc(open_ts_raw)};close_ts_utc={_scalar_iso_utc(close_ts_raw)};"
            f"close_minus_open_minutes={_fmt_num(close_minus_open_minutes)};"
            f"minute_cadence_pass={str(minute_cadence_pass).upper()};"
            f"first_meaningful_idx_pass={str(first_meaningful_idx_pass).upper()};"
            f"candidate_confirmation_ts={_scalar_iso_utc(confirmation_ts_raw)};"
            f"within_trade_window={str(within_trade_window).upper()}"
        )

        if minute_cadence_pass and first_meaningful_idx_pass and within_trade_window:
            wait_minutes = int(round(float(first_meaningful_idx)))
            return {
                "hindsight_confirmation_entry_ts_utc_v1": _scalar_iso_utc(confirmation_ts_raw),
                "hindsight_confirmation_entry_localizable_v1": True,
                "hindsight_confirmation_entry_reason_v1": "FIRST_MEANINGFUL_MFE_BAR_INDEX_MINUTE_CADENCE_LOCALIZATION",
                "hindsight_confirmation_entry_support_v1": confirmation_support,
                "hindsight_confirmation_entry_wait_bars_v1": wait_minutes,
                "hindsight_confirmation_entry_wait_minutes_v1": wait_minutes,
            }

        return {
            "hindsight_confirmation_entry_ts_utc_v1": _LEDGER_NOT_AVAILABLE,
            "hindsight_confirmation_entry_localizable_v1": False,
            "hindsight_confirmation_entry_reason_v1": "NO_LOCALIZABLE_CONFIRMATION_ENTRY",
            "hindsight_confirmation_entry_support_v1": confirmation_support,
            "hindsight_confirmation_entry_wait_bars_v1": pd.NA,
            "hindsight_confirmation_entry_wait_minutes_v1": pd.NA,
        }

    def _classify_entry_action_refined(
        *,
        entry_action: str,
        entry_hierarchy: Dict[str, Any],
        confirmation_localization: Dict[str, Any],
        confirmation_anchor: bool = False,
    ) -> Dict[str, Any]:
        refined_action = _resolve_entry_action_refined(
            entry_action=entry_action,
            entry_hierarchy=entry_hierarchy,
            confirmation_anchor=confirmation_anchor,
        )
        reason_family = _scalar_string(entry_hierarchy.get("hindsight_entry_reason_family_v1"))
        reason_code = _scalar_string(entry_hierarchy.get("hindsight_entry_reason_code_v1"))
        timing_review = _scalar_string(entry_hierarchy.get("hindsight_entry_timing_review_v1"))
        base_support = _scalar_string(entry_hierarchy.get("hindsight_entry_timing_support_v1"))
        confirmation_ts = _scalar_string(confirmation_localization.get("hindsight_confirmation_entry_ts_utc_v1"))
        confirmation_reason = _scalar_string(confirmation_localization.get("hindsight_confirmation_entry_reason_v1"))
        confirmation_support = _scalar_string(confirmation_localization.get("hindsight_confirmation_entry_support_v1"))
        confirmation_localizable = confirmation_localization.get("hindsight_confirmation_entry_localizable_v1")
        localizable_text = (
            str(bool(confirmation_localizable)).upper()
            if confirmation_localizable is not pd.NA and not _scalar_is_missing(confirmation_localizable)
            else "NA"
        )
        support = (
            f"refined_entry_action={refined_action};base_entry_action={entry_action};"
            f"confirmation_anchor={str(bool(confirmation_anchor)).upper()};"
            f"entry_timing_review={timing_review};entry_reason_family={reason_family};entry_reason_code={reason_code};"
            f"confirmation_entry_localizable={localizable_text};confirmation_entry_ts={confirmation_ts};"
            f"confirmation_entry_reason={confirmation_reason};base_entry_support={base_support};"
            f"confirmation_entry_support={confirmation_support}"
        )
        return {
            "hindsight_entry_action_refined_v1": refined_action,
            "hindsight_entry_action_refined_reason_family_v1": reason_family,
            "hindsight_entry_action_refined_reason_code_v1": reason_code,
            "hindsight_entry_action_refined_support_v1": support,
            "hindsight_entry_skip_v1": refined_action == "SKIP_ENTRY",
            "hindsight_entry_take_now_v1": refined_action == "TAKE_ENTRY_NOW",
            "hindsight_entry_wait_for_confirmation_v1": refined_action == "WAIT_FOR_CONFIRMATION_ENTRY",
            "hindsight_entry_action_unresolved_v1": refined_action == "ENTRY_ACTION_UNRESOLVED",
        }

    def _classify_management_hierarchy(
        mapping: Dict[str, Any],
        *,
        management_action: str,
        trade_bucket: str,
        exit_bucket: str,
        hold_value: float,
        exit_earlier_value: float,
        peak_mfe: float,
        peak_to_exit_giveback: float,
        earliest_ts: str,
        extra_support: str,
    ) -> Dict[str, Any]:
        meaningful_thr = _coalesce_numeric(mapping, ["meaningful_mfe_threshold_bps"])
        post_exit_mfe = _coalesce_numeric(
            mapping,
            [
                "online_exit_live__post_exit_mfe_bps_replay_end_obs",
                "post_exit_mfe_bps_replay_end_obs",
                "online_exit_live__post_exit_mfe_bps",
                "post_exit_mfe_bps",
            ],
        )
        early_exit_regret_flag = bool(
            _coalesce_bool(
                mapping,
                [
                    "online_exit_live__early_exit_regret_replay_end_obs",
                    "early_exit_regret_replay_end_obs",
                    "online_exit_live__early_exit_regret",
                    "early_exit_regret",
                ],
            )
            is True
        )
        realized_pnl = _coalesce_numeric(mapping, ["pnl_bps"])
        cata_flag = bool(
            _coalesce_bool(mapping, ["cata", "hindsight_cata_flag"]) is True
            or _scalar_string(mapping.get("trade_outcome_class")) == "cata"
            or trade_bucket == "cata_trade"
        )
        peak_idx = _coalesce_numeric(mapping, ["peak_mfe_bar_index"])
        bars_held_exit_state = _coalesce_numeric(mapping, ["bars_held_exit_state"])
        time_since_peak = float("nan")
        if np.isfinite(bars_held_exit_state) and np.isfinite(peak_idx):
            time_since_peak = max(0.0, float(bars_held_exit_state) - float(peak_idx))
        built_value = bool(
            np.isfinite(peak_mfe)
            and (
                (np.isfinite(meaningful_thr) and float(peak_mfe) >= float(meaningful_thr))
                or float(peak_mfe) > 0.0
            )
        )

        reason_family = "MANAGEMENT_REASON_UNRESOLVED"
        reason_code = "INSUFFICIENT_SIGNAL_SUPPORT"
        if management_action == "HOLD_LONGER":
            reason_family = "LEFT_VALUE_ON_TABLE"
            if early_exit_regret_flag:
                reason_code = "EARLY_EXIT_REGRET_CONFIRMED"
            elif (np.isfinite(post_exit_mfe) and float(post_exit_mfe) > 0.0) or (np.isfinite(hold_value) and float(hold_value) > 0.0):
                reason_code = "PREMATURE_EXIT_WITH_POST_EXIT_VALUE"
            else:
                reason_code = "INSUFFICIENT_SIGNAL_SUPPORT"
        elif management_action == "EXIT_EARLIER":
            reason_family = "PROFIT_PROTECTION_FAILURE"
            if cata_flag and built_value:
                reason_code = "CATA_AFTER_BUILT_VALUE"
            elif np.isfinite(realized_pnl) and (
                (np.isfinite(meaningful_thr) and float(realized_pnl) <= max(0.0, float(meaningful_thr)))
                or float(realized_pnl) <= 0.0
            ):
                reason_code = "RETURN_TOWARD_ENTRY"
            elif np.isfinite(time_since_peak) and float(time_since_peak) > 0.0:
                reason_code = "LATE_AFTER_PEAK"
            elif np.isfinite(peak_to_exit_giveback) and float(peak_to_exit_giveback) > 0.0:
                reason_code = "PEAK_TO_EXIT_GIVEBACK"
        elif management_action == "EXIT_OK":
            reason_family = "VALID_EXIT"
            if trade_bucket == "bad_trade" or (cata_flag and not built_value):
                reason_code = "CLEAN_RISK_REDUCTION"
            elif np.isfinite(post_exit_mfe) and np.isfinite(meaningful_thr) and float(post_exit_mfe) < float(meaningful_thr):
                reason_code = "LOW_LEFT_VALUE"
            else:
                reason_code = "NO_PROVABLE_BETTER_ACTION"
        else:
            reason_family = "MANAGEMENT_REASON_UNRESOLVED"
            if cata_flag and built_value and earliest_ts == _LEDGER_NOT_AVAILABLE:
                reason_code = "NO_LOCALIZABLE_BETTER_EXIT"
            elif cata_flag:
                reason_code = "CATA_WITHOUT_PROVABLE_EARLY_SAVE"

        support = (
            f"management_action={management_action};trade_bucket={trade_bucket};exit_bucket={exit_bucket};"
            f"post_exit_mfe_bps={_fmt_num(post_exit_mfe)};early_exit_regret={str(early_exit_regret_flag).upper()};"
            f"hold_longer_extra_value_bps={_fmt_num(hold_value)};exit_earlier_saved_bps={_fmt_num(exit_earlier_value)};"
            f"peak_mfe_bps={_fmt_num(peak_mfe)};peak_to_exit_giveback_bps={_fmt_num(peak_to_exit_giveback)};"
            f"meaningful_mfe_threshold_bps={_fmt_num(meaningful_thr)};realized_pnl_bps={_fmt_num(realized_pnl)};"
            f"time_since_peak_bars={_fmt_num(time_since_peak)};cata_flag={str(cata_flag).upper()};"
            f"earliest_provable_better_exit_ts={earliest_ts};{extra_support}"
        )
        return {
            "hindsight_teacher_hierarchy_domain_v1": "MANAGEMENT",
            "hindsight_teacher_hierarchy_action_family_v1": management_action,
            "hindsight_teacher_hierarchy_reason_family_v1": reason_family,
            "hindsight_teacher_hierarchy_reason_code_v1": reason_code,
            "hindsight_teacher_hierarchy_support_v1": support,
            "hindsight_teacher_hierarchy_path_v1": f"MANAGEMENT / {management_action} / {reason_family} / {reason_code}",
            "hindsight_entry_timing_review_v1": pd.NA,
            "hindsight_entry_reason_family_v1": pd.NA,
            "hindsight_entry_reason_code_v1": pd.NA,
            "hindsight_entry_timing_support_v1": pd.NA,
            "hindsight_wait_to_reduce_mae_v1": pd.NA,
            "hindsight_management_reason_family_v1": reason_family,
            "hindsight_management_reason_code_v1": reason_code,
            "hindsight_management_reason_support_v1": support,
            "hindsight_profit_protection_failure_v1": reason_family == "PROFIT_PROTECTION_FAILURE",
            "hindsight_left_value_on_table_v1": reason_family == "LEFT_VALUE_ON_TABLE",
            "hindsight_valid_exit_reason_v1": reason_code if reason_family == "VALID_EXIT" else _LEDGER_NOT_AVAILABLE,
        }

    policy_contract_value = f"{_ALL_TRADE_REVIEW_POLICY_ACTION_PROJECTION_LAYER}|HINDSIGHT_ONLY|NOT_LIVE_GATE|NOT_POLICY_TRUTH"

    def _project_policy_action_row(mapping: Dict[str, Any]) -> Dict[str, Any]:
        anchor_type = _scalar_string(mapping.get("hindsight_decision_anchor_type_v1"))
        anchor_domain = _scalar_string(mapping.get("hindsight_decision_anchor_domain_v1"))
        teacher_action = _scalar_string(mapping.get("hindsight_teacher_target_action_v1"))
        teacher_support = _scalar_string(mapping.get("hindsight_teacher_target_action_support_v1"))
        hierarchy_path = _scalar_string(mapping.get("hindsight_teacher_hierarchy_path_v1"))
        entry_refined = _scalar_string(mapping.get("hindsight_entry_action_refined_v1"))
        entry_reason_family = _scalar_string(mapping.get("hindsight_entry_action_refined_reason_family_v1"))
        entry_reason_code = _scalar_string(mapping.get("hindsight_entry_action_refined_reason_code_v1"))
        entry_support = _scalar_string(mapping.get("hindsight_entry_action_refined_support_v1"))
        management_reason_family = _scalar_string(mapping.get("hindsight_management_reason_family_v1"))
        management_reason_code = _scalar_string(mapping.get("hindsight_management_reason_code_v1"))
        management_support = _scalar_string(mapping.get("hindsight_management_reason_support_v1"))

        policy_domain = _LEDGER_NOT_AVAILABLE
        action_space = _LEDGER_NOT_AVAILABLE
        policy_action = "ACTION_UNRESOLVED"
        trainable = False
        projection_kind = "UNRESOLVED"
        diagnostic_reason = _LEDGER_NOT_AVAILABLE
        missed_window = False
        counterfactual_value = float("nan")
        counterfactual_source = "NOT_AVAILABLE"
        reason_family = _LEDGER_NOT_AVAILABLE
        reason_code = _LEDGER_NOT_AVAILABLE
        base_support = teacher_support

        if anchor_domain == "ENTRY_DECISION_REVIEW_V1":
            policy_domain = "ENTRY"
            action_space = "SKIP|TAKE_NOW|WAIT"
            reason_family = entry_reason_family if entry_reason_family != _LEDGER_NOT_AVAILABLE else _scalar_string(mapping.get("hindsight_teacher_hierarchy_reason_family_v1"))
            reason_code = entry_reason_code if entry_reason_code != _LEDGER_NOT_AVAILABLE else _scalar_string(mapping.get("hindsight_teacher_hierarchy_reason_code_v1"))
            base_support = entry_support if entry_support != _LEDGER_NOT_AVAILABLE else teacher_support
            if anchor_type == "ENTRY_DECISION_ANCHOR":
                if entry_refined == "SKIP_ENTRY":
                    policy_action = "SKIP"
                    trainable = True
                    projection_kind = "DIRECT_ENTRY_DECISION"
                    counterfactual_value = _scalar_float(mapping.get("hindsight_teacher_counterfactual_value_bps_v1"))
                    counterfactual_source = "SKIP_TRADE_AVOIDED_LOSS_BPS" if pd.notna(counterfactual_value) else "NOT_AVAILABLE"
                elif entry_refined == "TAKE_ENTRY_NOW":
                    policy_action = "TAKE_NOW"
                    trainable = True
                    projection_kind = "DIRECT_ENTRY_DECISION"
                    counterfactual_source = "SUPPORT_ONLY"
                elif entry_refined == "WAIT_FOR_CONFIRMATION_ENTRY":
                    policy_action = "WAIT"
                    trainable = True
                    projection_kind = "DIRECT_ENTRY_DECISION"
                    counterfactual_source = "SUPPORT_ONLY"
                else:
                    policy_action = "ACTION_UNRESOLVED"
                    projection_kind = "UNRESOLVED"
            elif anchor_type == "EARLIEST_PROVABLE_CONFIRMATION_ENTRY_ANCHOR":
                policy_action = "TAKE_NOW"
                trainable = True
                projection_kind = "LOCALIZED_CONFIRMATION_ENTRY"
                counterfactual_source = "SUPPORT_ONLY"
            else:
                policy_action = "ACTION_UNRESOLVED"
                projection_kind = "UNRESOLVED"
        elif anchor_domain == "TRADE_MANAGEMENT_REVIEW_V1":
            policy_domain = "MANAGEMENT"
            action_space = "HOLD|EXIT_NOW"
            reason_family = management_reason_family if management_reason_family != _LEDGER_NOT_AVAILABLE else _scalar_string(mapping.get("hindsight_teacher_hierarchy_reason_family_v1"))
            reason_code = management_reason_code if management_reason_code != _LEDGER_NOT_AVAILABLE else _scalar_string(mapping.get("hindsight_teacher_hierarchy_reason_code_v1"))
            base_support = management_support if management_support != _LEDGER_NOT_AVAILABLE else teacher_support
            if anchor_type == "ACTUAL_EXIT_DECISION_ANCHOR":
                if teacher_action == "HOLD_LONGER":
                    policy_action = "HOLD"
                    trainable = True
                    projection_kind = "DIRECT_ACTUAL_EXIT_DECISION"
                    counterfactual_value = _scalar_float(mapping.get("hindsight_teacher_counterfactual_value_bps_v1"))
                    counterfactual_source = "HOLD_LONGER_EXTRA_VALUE_BPS" if pd.notna(counterfactual_value) else "NOT_AVAILABLE"
                elif teacher_action == "EXIT_OK":
                    policy_action = "EXIT_NOW"
                    trainable = True
                    projection_kind = "DIRECT_ACTUAL_EXIT_DECISION"
                    counterfactual_source = "SUPPORT_ONLY"
                elif teacher_action == "MANAGEMENT_UNRESOLVED":
                    policy_action = "ACTION_UNRESOLVED"
                    projection_kind = "UNRESOLVED"
                elif teacher_action == "EXIT_EARLIER":
                    policy_action = "DIAGNOSTIC_ONLY"
                    projection_kind = "DIAGNOSTIC_ONLY"
                    diagnostic_reason = "MISSED_EARLIER_EXIT_WINDOW"
                    missed_window = True
                    counterfactual_value = _scalar_float(mapping.get("hindsight_teacher_counterfactual_value_bps_v1"))
                    counterfactual_source = "EXIT_EARLIER_SAVED_BPS_DIAGNOSTIC_ONLY" if pd.notna(counterfactual_value) else "NOT_AVAILABLE"
                else:
                    policy_action = "ACTION_UNRESOLVED"
                    projection_kind = "UNRESOLVED"
            elif anchor_type == "EARLIEST_PROVABLE_BETTER_EXIT_ANCHOR":
                policy_action = "EXIT_NOW"
                trainable = True
                projection_kind = "LOCALIZED_EARLIER_EXIT"
                counterfactual_value = _scalar_float(mapping.get("hindsight_teacher_counterfactual_value_bps_v1"))
                counterfactual_source = "EXIT_EARLIER_SAVED_BPS" if pd.notna(counterfactual_value) else "NOT_AVAILABLE"
            else:
                policy_action = "ACTION_UNRESOLVED"
                projection_kind = "UNRESOLVED"

        reason_path = f"{policy_domain} / {policy_action} / {reason_family} / {reason_code}"
        if not pd.notna(counterfactual_value):
            priority_abs = float("nan")
        else:
            priority_abs = abs(counterfactual_value)
        support = (
            f"policy_domain={policy_domain};policy_action_space={action_space};policy_action={policy_action};"
            f"trainable={str(bool(trainable)).upper()};projection_kind={projection_kind};"
            f"anchor_type={anchor_type};anchor_domain={anchor_domain};teacher_action={teacher_action};"
            f"entry_action_refined={entry_refined};reason_path={reason_path};"
            f"counterfactual_value_source={counterfactual_source};diagnostic_reason={diagnostic_reason};"
            f"base_teacher_hierarchy_path={hierarchy_path};base_support={base_support}"
        )
        return {
            "hindsight_policy_action_domain_v1": policy_domain,
            "hindsight_policy_action_space_v1": action_space,
            "hindsight_policy_action_v1": policy_action,
            "hindsight_policy_action_trainable_v1": trainable,
            "hindsight_policy_action_projection_kind_v1": projection_kind,
            "hindsight_policy_action_reason_path_v1": reason_path,
            "hindsight_policy_action_support_v1": support,
            "hindsight_policy_action_semantic_contract_v1": policy_contract_value,
            "hindsight_policy_skip_v1": policy_action == "SKIP",
            "hindsight_policy_take_now_v1": policy_action == "TAKE_NOW",
            "hindsight_policy_wait_v1": policy_action == "WAIT",
            "hindsight_policy_hold_v1": policy_action == "HOLD",
            "hindsight_policy_exit_now_v1": policy_action == "EXIT_NOW",
            "hindsight_policy_action_unresolved_v1": policy_action == "ACTION_UNRESOLVED",
            "hindsight_policy_diagnostic_only_v1": policy_action == "DIAGNOSTIC_ONLY",
            "hindsight_policy_diagnostic_reason_v1": diagnostic_reason,
            "hindsight_policy_missed_window_v1": missed_window,
            "hindsight_policy_counterfactual_value_bps_v1": counterfactual_value,
            "hindsight_policy_counterfactual_value_source_v1": counterfactual_source,
            "hindsight_policy_priority_abs_bps_v1": priority_abs,
        }

    if review_surface_df.empty:
        empty_df = pd.DataFrame({field: pd.Series(dtype="object") for field in bridge_field_names})
        for row in bridge_schema_rows:
            dtype = str(row["dtype"])
            field_name = str(row["field_name"])
            if dtype == "string":
                empty_df[field_name] = pd.Series(dtype="string")
            elif dtype == "float64":
                empty_df[field_name] = pd.Series(dtype="float64")
            elif dtype == "Int64":
                empty_df[field_name] = pd.Series(dtype="Int64")
            elif dtype == "boolean":
                empty_df[field_name] = pd.Series(dtype="boolean")
        return {
            "bridge_df": empty_df,
            "policy_action_teacher_trainable_df": empty_df.copy(),
            "summary": {
                "bridge_contract": contract_value,
                "bridge_mode": _ALL_TRADE_REVIEW_DECISION_MOMENT_BRIDGE_MODE,
                "control_date": str(control_date.isoformat()),
                "rows": 0,
                "anchor_type_counts": {},
                "anchor_domain_counts": {},
                "target_action_counts": {},
                "hierarchy_reason_family_counts": {},
                "hierarchy_reason_code_counts": {},
                "entry_timing_review_counts": {},
                "entry_action_refined_counts": {},
                "original_entry_anchor_target_action_counts": {},
                "original_entry_anchor_refined_action_counts": {},
                "policy_action_counts": {},
                "policy_projection_kind_counts": {},
                "policy_trainable_rows": 0,
                "policy_diagnostic_only_rows": 0,
                "policy_action_unresolved_rows": 0,
                "policy_trainable_action_counts": {},
                "policy_trainable_view_rows": 0,
                "entry_anchor_rows": 0,
                "actual_exit_anchor_rows": 0,
                "earliest_provable_better_exit_anchor_rows": 0,
                "earliest_provable_confirmation_entry_anchor_rows": 0,
                "join_ready_rows": 0,
                "confirmation_entry_trade_coverage": {
                    "wait_for_confirmation_trade_rows": 0,
                    "provable_confirmation_entry_trade_rows": 0,
                    "missing_confirmation_entry_trade_rows": 0,
                },
                "earliest_provable_better_exit_trade_coverage": {
                    "should_exit_earlier_trade_rows": 0,
                    "provable_better_exit_trade_rows": 0,
                    "missing_provable_better_exit_trade_rows": 0,
                },
                "semantic_contract": {
                    "mode": "HINDSIGHT_ONLY",
                    "surface_name": _ALL_TRADE_REVIEW_DECISION_MOMENT_BRIDGE_CONTRACT,
                    "sparsity": "SPARSE_ANCHORS_ONLY",
                    "entry_anchor_action_domain": "ENTRY_DECISION_REVIEW_V1",
                    "management_anchor_action_domain": "TRADE_MANAGEMENT_REVIEW_V1",
                    "hierarchy_layer": "HIERARCHICAL_TEACHER_REASON_SYSTEM_V1",
                    "entry_action_refinement_layer": "ACTIONABLE_ENTRY_TIMING_BRIDGE_V1",
                    "policy_action_projection_layer": _ALL_TRADE_REVIEW_POLICY_ACTION_PROJECTION_LAYER,
                    "confirmation_entry_anchor_semantics": "EARLIEST_PROVABLE_CONFIRMATION_ENTRY_NOT_OPTIMAL_ENTRY",
                    "trainable_policy_view_contract": _ALL_TRADE_REVIEW_POLICY_ACTION_TRAINABLE_VIEW_CONTRACT,
                    "not_live_gate": True,
                    "not_policy_truth": True,
                },
            },
        }

    records: List[Dict[str, Any]] = []
    should_exit_earlier_trade_rows = 0
    provable_better_exit_trade_rows = 0
    wait_for_confirmation_trade_rows = 0
    provable_confirmation_entry_trade_rows = 0

    for row in review_surface_df.to_dict(orient="records"):
        run_id = _scalar_string(row.get("run_id"))
        candidate_uid = _scalar_string(row.get("candidate_uid"))
        trade_uid = _scalar_string(row.get("trade_uid"))
        trade_id = _scalar_string(row.get("trade_id"))
        decision_ts = _scalar_iso_utc(row.get("decision_ts_utc"))
        entry_ts = _scalar_iso_utc(row.get("open_ts_utc"))
        exit_ts = _scalar_iso_utc(row.get("close_ts_utc"))

        trade_bucket = _scalar_string(row.get("post_trade_quality_bucket"))
        entry_bucket = _scalar_string(row.get("review_entry_bucket_v1"))
        exit_bucket = _scalar_string(row.get("review_exit_bucket_v1"))
        domain_support = _scalar_string(row.get("hindsight_rl_review_domain_support_v1"))
        full_reason = _scalar_string(row.get("hindsight_rl_review_reason_v1"))
        entry_reason = _extract_reason(full_reason, "entry=")
        management_reason = _extract_reason(full_reason, "management=")

        skip_value = _scalar_float(row.get("hindsight_skip_trade_avoided_loss_bps_v1"))
        hold_value = _scalar_float(row.get("hindsight_hold_longer_extra_value_bps_v1"))
        exit_earlier_value = _scalar_float(row.get("hindsight_exit_earlier_saved_bps_v1"))
        peak_mfe = _scalar_float(row.get("hindsight_peak_mfe_bps_v1"))
        peak_to_exit_giveback = _scalar_float(row.get("hindsight_peak_to_exit_giveback_bps_v1"))
        mae_bps = _coalesce_numeric(row, ["mae_bps"])

        entry_review = _scalar_string(row.get("hindsight_entry_decision_review_v1"))
        if entry_review == "SHOULD_SKIP_TRADE":
            entry_action = "SKIP_ENTRY"
            entry_counterfactual = skip_value
        elif entry_review == "TAKE_WAS_OK":
            entry_action = "TAKE_ENTRY"
            entry_counterfactual = 0.0
        else:
            entry_action = "ENTRY_UNRESOLVED"
            entry_counterfactual = float("nan")
        entry_support = (
            f"entry_review={entry_review};trade_bucket={trade_bucket};entry_bucket={entry_bucket};"
            f"skip_trade_avoided_loss_bps={skip_value if skip_value is not None else 'NA'};domain_support={domain_support}"
        )
        entry_hierarchy = _classify_entry_hierarchy(
            row,
            entry_action=entry_action,
            trade_bucket=trade_bucket,
            entry_bucket=entry_bucket,
            skip_value=skip_value,
            peak_mfe=peak_mfe,
            mae_bps=mae_bps,
        )
        entry_confirmation_localization = _localize_confirmation_entry(
            row,
            refined_action=_resolve_entry_action_refined(
                entry_action=entry_action,
                entry_hierarchy=entry_hierarchy,
            ),
        )
        entry_action_refined = _classify_entry_action_refined(
            entry_action=entry_action,
            entry_hierarchy=entry_hierarchy,
            confirmation_localization=entry_confirmation_localization,
        )
        if entry_action_refined.get("hindsight_entry_action_refined_v1") == "WAIT_FOR_CONFIRMATION_ENTRY":
            wait_for_confirmation_trade_rows += 1
            if bool(entry_confirmation_localization.get("hindsight_confirmation_entry_localizable_v1") is True):
                provable_confirmation_entry_trade_rows += 1
        entry_join_ready = bool(
            all(
                _nonmissing_string(x)
                for x in [run_id, candidate_uid, trade_uid, trade_id, decision_ts, decision_ts]
            )
        )
        records.append(
            {
                "run_id": run_id,
                "candidate_uid": candidate_uid,
                "trade_uid": trade_uid,
                "trade_id": trade_id,
                "decision_timestamp": decision_ts,
                "entry_timestamp": entry_ts,
                "exit_timestamp": exit_ts,
                "hindsight_decision_anchor_type_v1": "ENTRY_DECISION_ANCHOR",
                "hindsight_decision_anchor_domain_v1": "ENTRY_DECISION_REVIEW_V1",
                "hindsight_decision_anchor_timestamp_utc_v1": decision_ts,
                "hindsight_teacher_target_action_v1": entry_action,
                "hindsight_teacher_target_action_reason_v1": entry_reason,
                "hindsight_teacher_target_action_support_v1": entry_support,
                **entry_hierarchy,
                **entry_action_refined,
                "hindsight_entry_anchor_review_v1": entry_action,
                "hindsight_entry_anchor_skip_trade_v1": entry_action == "SKIP_ENTRY",
                "hindsight_entry_anchor_take_trade_v1": entry_action == "TAKE_ENTRY",
                "hindsight_entry_anchor_unresolved_v1": entry_action == "ENTRY_UNRESOLVED",
                **entry_confirmation_localization,
                "hindsight_management_anchor_review_v1": pd.NA,
                "hindsight_management_anchor_hold_longer_v1": pd.NA,
                "hindsight_management_anchor_exit_ok_v1": pd.NA,
                "hindsight_management_anchor_exit_earlier_v1": pd.NA,
                "hindsight_management_anchor_unresolved_v1": pd.NA,
                "hindsight_teacher_counterfactual_value_bps_v1": entry_counterfactual,
                "hindsight_teacher_priority_bps_v1": entry_counterfactual,
                "hindsight_teacher_priority_abs_bps_v1": abs(entry_counterfactual) if pd.notna(entry_counterfactual) else float("nan"),
                "hindsight_earliest_provable_better_exit_ts_utc_v1": _LEDGER_NOT_AVAILABLE,
                "hindsight_earliest_provable_better_exit_reason_v1": _LEDGER_NOT_AVAILABLE,
                "hindsight_earliest_provable_better_exit_support_v1": _LEDGER_NOT_AVAILABLE,
                "hindsight_teacher_bridge_contract_v1": contract_value,
                "hindsight_teacher_join_ready_v1": entry_join_ready,
            }
        )

        confirmation_entry_ts = _scalar_string(entry_confirmation_localization.get("hindsight_confirmation_entry_ts_utc_v1"))
        if entry_action_refined.get("hindsight_entry_action_refined_v1") == "WAIT_FOR_CONFIRMATION_ENTRY" and confirmation_entry_ts != _LEDGER_NOT_AVAILABLE:
            confirmation_join_ready = bool(
                all(
                    _nonmissing_string(x)
                    for x in [run_id, candidate_uid, trade_uid, trade_id, decision_ts, confirmation_entry_ts]
                )
            )
            confirmation_refined = _classify_entry_action_refined(
                entry_action="TAKE_ENTRY",
                entry_hierarchy=entry_hierarchy,
                confirmation_localization=entry_confirmation_localization,
                confirmation_anchor=True,
            )
            records.append(
                {
                    "run_id": run_id,
                    "candidate_uid": candidate_uid,
                    "trade_uid": trade_uid,
                    "trade_id": trade_id,
                    "decision_timestamp": decision_ts,
                    "entry_timestamp": entry_ts,
                    "exit_timestamp": exit_ts,
                    "hindsight_decision_anchor_type_v1": "EARLIEST_PROVABLE_CONFIRMATION_ENTRY_ANCHOR",
                    "hindsight_decision_anchor_domain_v1": "ENTRY_DECISION_REVIEW_V1",
                    "hindsight_decision_anchor_timestamp_utc_v1": confirmation_entry_ts,
                    "hindsight_teacher_target_action_v1": "TAKE_ENTRY_NOW",
                    "hindsight_teacher_target_action_reason_v1": _scalar_string(entry_confirmation_localization.get("hindsight_confirmation_entry_reason_v1")),
                    "hindsight_teacher_target_action_support_v1": _scalar_string(entry_confirmation_localization.get("hindsight_confirmation_entry_support_v1")),
                    **entry_hierarchy,
                    **confirmation_refined,
                    "hindsight_entry_anchor_review_v1": "TAKE_ENTRY",
                    "hindsight_entry_anchor_skip_trade_v1": False,
                    "hindsight_entry_anchor_take_trade_v1": True,
                    "hindsight_entry_anchor_unresolved_v1": False,
                    **entry_confirmation_localization,
                    "hindsight_management_anchor_review_v1": pd.NA,
                    "hindsight_management_anchor_hold_longer_v1": pd.NA,
                    "hindsight_management_anchor_exit_ok_v1": pd.NA,
                    "hindsight_management_anchor_exit_earlier_v1": pd.NA,
                    "hindsight_management_anchor_unresolved_v1": pd.NA,
                    "hindsight_teacher_counterfactual_value_bps_v1": 0.0,
                    "hindsight_teacher_priority_bps_v1": 0.0,
                    "hindsight_teacher_priority_abs_bps_v1": 0.0,
                    "hindsight_earliest_provable_better_exit_ts_utc_v1": _LEDGER_NOT_AVAILABLE,
                    "hindsight_earliest_provable_better_exit_reason_v1": _LEDGER_NOT_AVAILABLE,
                    "hindsight_earliest_provable_better_exit_support_v1": _LEDGER_NOT_AVAILABLE,
                    "hindsight_teacher_bridge_contract_v1": contract_value,
                    "hindsight_teacher_join_ready_v1": confirmation_join_ready,
                }
            )

        management_review = _scalar_string(row.get("hindsight_management_review_v1"))
        if management_review == "SHOULD_HOLD_LONGER":
            management_action = "HOLD_LONGER"
            management_counterfactual = hold_value
        elif management_review == "SHOULD_EXIT_EARLIER":
            management_action = "EXIT_EARLIER"
            management_counterfactual = exit_earlier_value
            should_exit_earlier_trade_rows += 1
        elif management_review == "MANAGED_OK":
            management_action = "EXIT_OK"
            management_counterfactual = 0.0
        else:
            management_action = "MANAGEMENT_UNRESOLVED"
            management_counterfactual = float("nan")

        earliest_ts = _LEDGER_NOT_AVAILABLE
        earliest_reason = _LEDGER_NOT_AVAILABLE
        earliest_support = _LEDGER_NOT_AVAILABLE
        if management_action == "EXIT_EARLIER":
            open_ts_raw = pd.to_datetime(pd.Series([row.get("open_ts_utc")]), utc=True, errors="coerce").iloc[0]
            close_ts_raw = pd.to_datetime(pd.Series([row.get("close_ts_utc")]), utc=True, errors="coerce").iloc[0]
            peak_idx = pd.to_numeric(pd.Series([row.get("peak_mfe_bar_index")]), errors="coerce").iloc[0]
            bars_held_exit_state = pd.to_numeric(pd.Series([row.get("bars_held_exit_state")]), errors="coerce").iloc[0]
            close_minus_open_minutes = float("nan")
            if pd.notna(open_ts_raw) and pd.notna(close_ts_raw):
                close_minus_open_minutes = float((close_ts_raw - open_ts_raw).total_seconds() / 60.0)
            minute_cadence_pass = bool(
                pd.notna(open_ts_raw)
                and pd.notna(close_ts_raw)
                and np.isfinite(close_minus_open_minutes)
                and np.isfinite(float(bars_held_exit_state))
                and abs(close_minus_open_minutes - float(bars_held_exit_state)) <= 1e-6
            )
            peak_idx_pass = bool(
                np.isfinite(float(peak_idx))
                and float(peak_idx) >= 0.0
                and np.isfinite(float(bars_held_exit_state))
                and float(peak_idx) <= float(bars_held_exit_state)
            )
            if minute_cadence_pass and peak_idx_pass and pd.notna(open_ts_raw):
                candidate_ts = open_ts_raw + pd.Timedelta(minutes=float(peak_idx))
                if (
                    pd.notna(candidate_ts)
                    and pd.notna(close_ts_raw)
                    and candidate_ts < close_ts_raw
                    and pd.notna(exit_earlier_value)
                    and float(exit_earlier_value) > 0.0
                ):
                    earliest_ts = _scalar_iso_utc(candidate_ts)
                    earliest_reason = "PEAK_MFE_BAR_INDEX_MINUTE_CADENCE_LOCALIZATION"
                    earliest_support = (
                        f"open_ts_utc={_scalar_iso_utc(open_ts_raw)};close_ts_utc={_scalar_iso_utc(close_ts_raw)};"
                        f"peak_mfe_bar_index={float(peak_idx):.6f};bars_held_exit_state={float(bars_held_exit_state):.6f};"
                        f"close_minus_open_minutes={close_minus_open_minutes:.6f};exit_earlier_saved_bps={float(exit_earlier_value):.6f}"
                    )
                    provable_better_exit_trade_rows += 1

        management_support = (
            f"management_review={management_review};trade_bucket={trade_bucket};exit_bucket={exit_bucket};"
            f"hold_longer_extra_value_bps={hold_value if hold_value is not None else 'NA'};"
            f"exit_earlier_saved_bps={exit_earlier_value if exit_earlier_value is not None else 'NA'};"
            f"peak_mfe_bps={peak_mfe if peak_mfe is not None else 'NA'};"
            f"peak_to_exit_giveback_bps={peak_to_exit_giveback if peak_to_exit_giveback is not None else 'NA'};"
            f"domain_support={domain_support};earliest_provable_better_exit_ts={earliest_ts}"
        )
        management_hierarchy = _classify_management_hierarchy(
            row,
            management_action=management_action,
            trade_bucket=trade_bucket,
            exit_bucket=exit_bucket,
            hold_value=hold_value,
            exit_earlier_value=exit_earlier_value,
            peak_mfe=peak_mfe,
            peak_to_exit_giveback=peak_to_exit_giveback,
            earliest_ts=earliest_ts,
            extra_support=f"domain_support={domain_support}",
        )
        management_join_ready = bool(
            all(
                _nonmissing_string(x)
                for x in [run_id, candidate_uid, trade_uid, trade_id, decision_ts, exit_ts, exit_ts]
            )
        )
        records.append(
            {
                "run_id": run_id,
                "candidate_uid": candidate_uid,
                "trade_uid": trade_uid,
                "trade_id": trade_id,
                "decision_timestamp": decision_ts,
                "entry_timestamp": entry_ts,
                "exit_timestamp": exit_ts,
                "hindsight_decision_anchor_type_v1": "ACTUAL_EXIT_DECISION_ANCHOR",
                "hindsight_decision_anchor_domain_v1": "TRADE_MANAGEMENT_REVIEW_V1",
                "hindsight_decision_anchor_timestamp_utc_v1": exit_ts,
                "hindsight_teacher_target_action_v1": management_action,
                "hindsight_teacher_target_action_reason_v1": management_reason,
                "hindsight_teacher_target_action_support_v1": management_support,
                **management_hierarchy,
                "hindsight_entry_action_refined_v1": pd.NA,
                "hindsight_entry_action_refined_reason_family_v1": pd.NA,
                "hindsight_entry_action_refined_reason_code_v1": pd.NA,
                "hindsight_entry_action_refined_support_v1": pd.NA,
                "hindsight_entry_skip_v1": pd.NA,
                "hindsight_entry_take_now_v1": pd.NA,
                "hindsight_entry_wait_for_confirmation_v1": pd.NA,
                "hindsight_entry_action_unresolved_v1": pd.NA,
                "hindsight_entry_anchor_review_v1": pd.NA,
                "hindsight_entry_anchor_skip_trade_v1": pd.NA,
                "hindsight_entry_anchor_take_trade_v1": pd.NA,
                "hindsight_entry_anchor_unresolved_v1": pd.NA,
                "hindsight_confirmation_entry_ts_utc_v1": _LEDGER_NOT_AVAILABLE,
                "hindsight_confirmation_entry_localizable_v1": pd.NA,
                "hindsight_confirmation_entry_reason_v1": _LEDGER_NOT_AVAILABLE,
                "hindsight_confirmation_entry_support_v1": _LEDGER_NOT_AVAILABLE,
                "hindsight_confirmation_entry_wait_bars_v1": pd.NA,
                "hindsight_confirmation_entry_wait_minutes_v1": pd.NA,
                "hindsight_management_anchor_review_v1": management_action,
                "hindsight_management_anchor_hold_longer_v1": management_action == "HOLD_LONGER",
                "hindsight_management_anchor_exit_ok_v1": management_action == "EXIT_OK",
                "hindsight_management_anchor_exit_earlier_v1": management_action == "EXIT_EARLIER",
                "hindsight_management_anchor_unresolved_v1": management_action == "MANAGEMENT_UNRESOLVED",
                "hindsight_teacher_counterfactual_value_bps_v1": management_counterfactual,
                "hindsight_teacher_priority_bps_v1": management_counterfactual,
                "hindsight_teacher_priority_abs_bps_v1": abs(management_counterfactual) if pd.notna(management_counterfactual) else float("nan"),
                "hindsight_earliest_provable_better_exit_ts_utc_v1": earliest_ts,
                "hindsight_earliest_provable_better_exit_reason_v1": earliest_reason,
                "hindsight_earliest_provable_better_exit_support_v1": earliest_support,
                "hindsight_teacher_bridge_contract_v1": contract_value,
                "hindsight_teacher_join_ready_v1": management_join_ready,
            }
        )

        if management_action == "EXIT_EARLIER" and earliest_ts != _LEDGER_NOT_AVAILABLE:
            earlier_join_ready = bool(
                all(
                    _nonmissing_string(x)
                    for x in [run_id, candidate_uid, trade_uid, trade_id, decision_ts, earliest_ts]
                )
            )
            earlier_hierarchy = _classify_management_hierarchy(
                row,
                management_action="EXIT_EARLIER",
                trade_bucket=trade_bucket,
                exit_bucket=exit_bucket,
                hold_value=hold_value,
                exit_earlier_value=exit_earlier_value,
                peak_mfe=peak_mfe,
                peak_to_exit_giveback=peak_to_exit_giveback,
                earliest_ts=earliest_ts,
                extra_support=earliest_support,
            )
            records.append(
                {
                    "run_id": run_id,
                    "candidate_uid": candidate_uid,
                    "trade_uid": trade_uid,
                    "trade_id": trade_id,
                    "decision_timestamp": decision_ts,
                    "entry_timestamp": entry_ts,
                    "exit_timestamp": exit_ts,
                    "hindsight_decision_anchor_type_v1": "EARLIEST_PROVABLE_BETTER_EXIT_ANCHOR",
                    "hindsight_decision_anchor_domain_v1": "TRADE_MANAGEMENT_REVIEW_V1",
                    "hindsight_decision_anchor_timestamp_utc_v1": earliest_ts,
                    "hindsight_teacher_target_action_v1": "EXIT_EARLIER",
                    "hindsight_teacher_target_action_reason_v1": earliest_reason,
                    "hindsight_teacher_target_action_support_v1": earliest_support,
                    **earlier_hierarchy,
                    "hindsight_entry_action_refined_v1": pd.NA,
                    "hindsight_entry_action_refined_reason_family_v1": pd.NA,
                    "hindsight_entry_action_refined_reason_code_v1": pd.NA,
                    "hindsight_entry_action_refined_support_v1": pd.NA,
                    "hindsight_entry_skip_v1": pd.NA,
                    "hindsight_entry_take_now_v1": pd.NA,
                    "hindsight_entry_wait_for_confirmation_v1": pd.NA,
                    "hindsight_entry_action_unresolved_v1": pd.NA,
                    "hindsight_entry_anchor_review_v1": pd.NA,
                    "hindsight_entry_anchor_skip_trade_v1": pd.NA,
                    "hindsight_entry_anchor_take_trade_v1": pd.NA,
                    "hindsight_entry_anchor_unresolved_v1": pd.NA,
                    "hindsight_confirmation_entry_ts_utc_v1": _LEDGER_NOT_AVAILABLE,
                    "hindsight_confirmation_entry_localizable_v1": pd.NA,
                    "hindsight_confirmation_entry_reason_v1": _LEDGER_NOT_AVAILABLE,
                    "hindsight_confirmation_entry_support_v1": _LEDGER_NOT_AVAILABLE,
                    "hindsight_confirmation_entry_wait_bars_v1": pd.NA,
                    "hindsight_confirmation_entry_wait_minutes_v1": pd.NA,
                    "hindsight_management_anchor_review_v1": "EXIT_EARLIER",
                    "hindsight_management_anchor_hold_longer_v1": False,
                    "hindsight_management_anchor_exit_ok_v1": False,
                    "hindsight_management_anchor_exit_earlier_v1": True,
                    "hindsight_management_anchor_unresolved_v1": False,
                    "hindsight_teacher_counterfactual_value_bps_v1": management_counterfactual,
                    "hindsight_teacher_priority_bps_v1": management_counterfactual,
                    "hindsight_teacher_priority_abs_bps_v1": abs(management_counterfactual) if pd.notna(management_counterfactual) else float("nan"),
                    "hindsight_earliest_provable_better_exit_ts_utc_v1": earliest_ts,
                    "hindsight_earliest_provable_better_exit_reason_v1": earliest_reason,
                    "hindsight_earliest_provable_better_exit_support_v1": earliest_support,
                    "hindsight_teacher_bridge_contract_v1": contract_value,
                    "hindsight_teacher_join_ready_v1": earlier_join_ready,
                }
            )

    bridge_df = pd.DataFrame.from_records(records)
    if not bridge_df.empty:
        policy_projection_rows = [_project_policy_action_row(rec) for rec in bridge_df.to_dict(orient="records")]
        policy_projection_df = pd.DataFrame.from_records(policy_projection_rows, index=bridge_df.index)
        bridge_df = pd.concat([bridge_df, policy_projection_df], axis=1)
    for field_name in bridge_field_names:
        if field_name not in bridge_df.columns:
            bridge_df[field_name] = pd.NA
    bridge_df = bridge_df[bridge_field_names].copy()
    bridge_df = _cast_closed_trade_ledger_types(bridge_df, bridge_schema_rows)
    bridge_df = bridge_df.sort_values(
        ["run_id", "decision_timestamp", "trade_id", "hindsight_decision_anchor_timestamp_utc_v1", "hindsight_decision_anchor_type_v1"],
        kind="mergesort",
    ).reset_index(drop=True)

    policy_action_teacher_trainable_df = bridge_df.loc[
        bridge_df["hindsight_policy_action_trainable_v1"].fillna(False)
    ].copy()

    anchor_type_counts = _string_counts(bridge_df["hindsight_decision_anchor_type_v1"])
    anchor_domain_counts = _string_counts(bridge_df["hindsight_decision_anchor_domain_v1"])
    target_action_counts = _string_counts(bridge_df["hindsight_teacher_target_action_v1"])
    hierarchy_reason_family_counts = _string_counts(bridge_df["hindsight_teacher_hierarchy_reason_family_v1"])
    hierarchy_reason_code_counts = _string_counts(bridge_df["hindsight_teacher_hierarchy_reason_code_v1"])
    entry_timing_review_counts = _string_counts(bridge_df["hindsight_entry_timing_review_v1"])
    entry_action_refined_counts = _string_counts(bridge_df["hindsight_entry_action_refined_v1"])
    policy_action_counts = _string_counts(bridge_df["hindsight_policy_action_v1"])
    policy_projection_kind_counts = _string_counts(bridge_df["hindsight_policy_action_projection_kind_v1"])
    policy_trainable_action_counts = _string_counts(policy_action_teacher_trainable_df["hindsight_policy_action_v1"])
    original_entry_anchor_df = bridge_df.loc[
        bridge_df["hindsight_decision_anchor_type_v1"].astype("string").eq("ENTRY_DECISION_ANCHOR")
    ].copy()
    original_entry_anchor_target_action_counts = _string_counts(original_entry_anchor_df["hindsight_teacher_target_action_v1"])
    original_entry_anchor_refined_action_counts = _string_counts(original_entry_anchor_df["hindsight_entry_action_refined_v1"])
    summary = {
        "bridge_contract": contract_value,
        "bridge_mode": _ALL_TRADE_REVIEW_DECISION_MOMENT_BRIDGE_MODE,
        "control_date": str(control_date.isoformat()),
        "rows": int(len(bridge_df)),
        "anchor_type_counts": anchor_type_counts,
        "anchor_domain_counts": anchor_domain_counts,
        "target_action_counts": target_action_counts,
        "hierarchy_reason_family_counts": hierarchy_reason_family_counts,
        "hierarchy_reason_code_counts": hierarchy_reason_code_counts,
        "entry_timing_review_counts": entry_timing_review_counts,
        "entry_action_refined_counts": entry_action_refined_counts,
        "original_entry_anchor_target_action_counts": original_entry_anchor_target_action_counts,
        "original_entry_anchor_refined_action_counts": original_entry_anchor_refined_action_counts,
        "policy_action_counts": policy_action_counts,
        "policy_projection_kind_counts": policy_projection_kind_counts,
        "policy_trainable_rows": int(bridge_df["hindsight_policy_action_trainable_v1"].fillna(False).sum()),
        "policy_diagnostic_only_rows": int(bridge_df["hindsight_policy_diagnostic_only_v1"].fillna(False).sum()),
        "policy_action_unresolved_rows": int(bridge_df["hindsight_policy_action_unresolved_v1"].fillna(False).sum()),
        "policy_trainable_action_counts": policy_trainable_action_counts,
        "policy_trainable_view_rows": int(len(policy_action_teacher_trainable_df)),
        "entry_anchor_rows": int(anchor_type_counts.get("ENTRY_DECISION_ANCHOR", 0)),
        "actual_exit_anchor_rows": int(anchor_type_counts.get("ACTUAL_EXIT_DECISION_ANCHOR", 0)),
        "earliest_provable_better_exit_anchor_rows": int(anchor_type_counts.get("EARLIEST_PROVABLE_BETTER_EXIT_ANCHOR", 0)),
        "earliest_provable_confirmation_entry_anchor_rows": int(anchor_type_counts.get("EARLIEST_PROVABLE_CONFIRMATION_ENTRY_ANCHOR", 0)),
        "join_ready_rows": int(bridge_df["hindsight_teacher_join_ready_v1"].fillna(False).sum()),
        "confirmation_entry_trade_coverage": {
            "wait_for_confirmation_trade_rows": int(wait_for_confirmation_trade_rows),
            "provable_confirmation_entry_trade_rows": int(provable_confirmation_entry_trade_rows),
            "missing_confirmation_entry_trade_rows": int(max(0, wait_for_confirmation_trade_rows - provable_confirmation_entry_trade_rows)),
        },
        "earliest_provable_better_exit_trade_coverage": {
            "should_exit_earlier_trade_rows": int(should_exit_earlier_trade_rows),
            "provable_better_exit_trade_rows": int(provable_better_exit_trade_rows),
            "missing_provable_better_exit_trade_rows": int(max(0, should_exit_earlier_trade_rows - provable_better_exit_trade_rows)),
        },
        "semantic_contract": {
            "mode": "HINDSIGHT_ONLY",
            "surface_name": _ALL_TRADE_REVIEW_DECISION_MOMENT_BRIDGE_CONTRACT,
            "sparsity": "SPARSE_ANCHORS_ONLY",
            "entry_anchor_action_domain": "ENTRY_DECISION_REVIEW_V1",
            "management_anchor_action_domain": "TRADE_MANAGEMENT_REVIEW_V1",
            "hierarchy_layer": "HIERARCHICAL_TEACHER_REASON_SYSTEM_V1",
            "entry_action_refinement_layer": "ACTIONABLE_ENTRY_TIMING_BRIDGE_V1",
            "policy_action_projection_layer": _ALL_TRADE_REVIEW_POLICY_ACTION_PROJECTION_LAYER,
            "confirmation_entry_anchor_semantics": "EARLIEST_PROVABLE_CONFIRMATION_ENTRY_NOT_OPTIMAL_ENTRY",
            "trainable_policy_view_contract": _ALL_TRADE_REVIEW_POLICY_ACTION_TRAINABLE_VIEW_CONTRACT,
            "not_live_gate": True,
            "not_policy_truth": True,
        },
    }
    return {
        "bridge_df": bridge_df,
        "policy_action_teacher_trainable_df": policy_action_teacher_trainable_df,
        "summary": summary,
    }


