    def _counts(frame: pd.DataFrame, column: str) -> Dict[str, int]:
        if frame.empty or column not in frame.columns:
            return {}
        return {
            str(key): int(value)
            for key, value in frame[column].astype("string").value_counts(dropna=False).to_dict().items()
        }

    def _nested_counts(frame: pd.DataFrame, group_col: str, status_col: str) -> Dict[str, Dict[str, int]]:
        if frame.empty:
            return {}
        grouped = (
            frame.groupby([group_col, status_col], dropna=False)
            .size()
            .unstack(fill_value=0)
            .sort_index(kind="mergesort")
        )
        out: Dict[str, Dict[str, int]] = {}
        for idx, row in grouped.iterrows():
            out[str(idx)] = {str(col): int(val) for col, val in row.to_dict().items()}
        return out

