def build_shadow_meta_v2_test_01_threshold_frontier_artifacts(
    reports_root: Path = _TRUTH_E2E_REPORTS_ROOT,
    *,
    manifest_path: Path | None = None,
) -> Dict[str, Any]:
    context = _load_shadow_meta_v2_model_context(reports_root, manifest_path=manifest_path)
    shield_file = reports_root / "shadow_meta_validation_line_v2_prefreeze_shield_selection.json"
    shield_summary = json.loads(shield_file.read_text())
    frozen_shield_pocket = str(shield_summary.get("selected_shield_pocket"))
    threshold_df = _BASE.build_threshold_sweep(context["val_eval"]).copy()
    supported_thresholds = sorted(float(x) for x in threshold_df["threshold"].drop_duplicates().tolist())

    prefreeze_rows: List[Dict[str, Any]] = []
    for threshold in supported_thresholds:
        summary = _threshold_surface_summary(
            context["val_eval"],
            threshold=float(threshold),
            shield_pocket=frozen_shield_pocket,
        )
        prefreeze_rows.append(
            {
                "test_name": "TEST_01_THRESHOLD_FRONTIER",
                "selection_scope": "prefreeze_val_same_audit_only_frame",
                "threshold": float(threshold),
                "frozen_shield_pocket": frozen_shield_pocket,
                **summary,
                "is_threshold_0p5": bool(float(threshold) == 0.5),
            }
        )
    prefreeze_df = pd.DataFrame(prefreeze_rows)
    frontier_df = _non_dominated_audit_surface_frontier(prefreeze_df)
    frontier_df["prefreeze_selection_status"] = "PREFREEZE_THRESHOLD_FRONTIER_ESTABLISHED"

    holdout_rows: List[Dict[str, Any]] = []
    selected_threshold = float(0.5)
    candidate_thresholds = sorted({float(x) for x in frontier_df["threshold"].drop_duplicates().tolist()} | {selected_threshold})
    for threshold in candidate_thresholds:
        _, aggregate = _build_holdout_by_run_surface(
            context["holdout_full_df"],
            context["holdout_eval"],
            context["holdout_run_ids"],
            threshold=float(threshold),
            shield_pocket=frozen_shield_pocket,
            dom_field="threshold_frontier_dom_v2",
        )
        holdout_rows.append(
            {
                "test_name": "TEST_01_THRESHOLD_FRONTIER",
                "threshold": float(threshold),
                "frozen_shield_pocket": frozen_shield_pocket,
                "holdout_runs_total": int(aggregate["holdout_runs_total"]),
                "audited_runs": int(aggregate["audited_runs"]),
                "zero_traffic_runs": int(aggregate["zero_traffic_runs"]),
                "correct_cata_veto": int(aggregate["correct_cata_veto"]),
                "false_veto_total": int(aggregate["false_veto_total"]),
                "false_veto_selected_shield_pocket": int(aggregate["false_veto_selected_shield_pocket"]),
                "positive_exit_retention": float(aggregate["positive_exit_retention"]),
                "cata_capture": float(aggregate["cata_capture"]),
                "kept_pnl_total": float(aggregate["kept_pnl_total"]),
                "veto_pnl_total": float(aggregate["veto_pnl_total"]),
                "is_threshold_0p5": bool(float(threshold) == 0.5),
            }
        )
    holdout_df = pd.DataFrame(holdout_rows).sort_values(
        ["is_threshold_0p5", "correct_cata_veto", "false_veto_total", "threshold"],
        ascending=[False, False, True, True],
    ).reset_index(drop=True)
    selected_holdout = holdout_df.loc[holdout_df["threshold"].eq(selected_threshold)]
    selected_holdout_row = selected_holdout.iloc[0].to_dict() if not selected_holdout.empty else None
    frontier_thresholds = [float(x) for x in frontier_df["threshold"].tolist()]
    holdout_dominators = holdout_df.loc[
        holdout_df["threshold"].ne(selected_threshold)
        & holdout_df["threshold"].isin(frontier_thresholds)
        & holdout_df["false_veto_total"].le(float(selected_holdout_row["false_veto_total"]) if selected_holdout_row else float("inf"))
        & holdout_df["false_veto_selected_shield_pocket"].le(
            float(selected_holdout_row["false_veto_selected_shield_pocket"]) if selected_holdout_row else float("inf")
        )
        & holdout_df["positive_exit_retention"].ge(
            float(selected_holdout_row["positive_exit_retention"]) if selected_holdout_row else float("-inf")
        )
        & holdout_df["cata_capture"].ge(float(selected_holdout_row["cata_capture"]) if selected_holdout_row else float("-inf"))
        & holdout_df["kept_pnl_total"].ge(float(selected_holdout_row["kept_pnl_total"]) if selected_holdout_row else float("-inf"))
    ].copy()
    if selected_holdout_row is not None:
        holdout_dominators = holdout_dominators.loc[
            (holdout_dominators["false_veto_total"] < float(selected_holdout_row["false_veto_total"]))
            | (
                holdout_dominators["false_veto_selected_shield_pocket"]
                < float(selected_holdout_row["false_veto_selected_shield_pocket"])
            )
            | (holdout_dominators["positive_exit_retention"] > float(selected_holdout_row["positive_exit_retention"]))
            | (holdout_dominators["cata_capture"] > float(selected_holdout_row["cata_capture"]))
            | (holdout_dominators["kept_pnl_total"] > float(selected_holdout_row["kept_pnl_total"]))
        ].copy()
    winning_alt_holdout = (
        holdout_dominators.sort_values(
            ["false_veto_total", "positive_exit_retention", "cata_capture", "kept_pnl_total", "threshold"],
            ascending=[True, False, False, False, True],
        ).iloc[0].to_dict()
        if not holdout_dominators.empty
        else None
    )

    if frontier_df.empty:
        verdict = "NO_ROBUST_THRESHOLD_ESTABLISHED"
        keep_or_kill = "KILL_AS_UNSUPPORTED"
        refreeze_recommendation = "KEEP_0P5_BASELINE"
    elif winning_alt_holdout is not None:
        verdict = "ALT_THRESHOLD_BETTER_PREFREEZE"
        keep_or_kill = "KEEP_FOR_FURTHER_WORK"
        refreeze_recommendation = "REFREEZE_TO_ALT_THRESHOLD"
    elif len(frontier_thresholds) > 1:
        verdict = "MULTI_THRESHOLD_FRONTIER"
        keep_or_kill = "KEEP_FOR_FURTHER_WORK"
        refreeze_recommendation = "KEEP_0P5_BASELINE"
    else:
        verdict = "THRESHOLD_0P5_CONFIRMED"
        keep_or_kill = "KEEP_FOR_FURTHER_WORK"
        refreeze_recommendation = "KEEP_0P5_BASELINE"
    summary = {
        "test_name": "TEST_01_THRESHOLD_FRONTIER",
        "validation_line_name": _SHADOW_V2_VALIDATION_LINE_NAME,
        "source_manifest_path": context["manifest_path"],
        "source_shield_selection_path": str(shield_file),
        "same_audit_only_frame_as_v2_baseline": True,
        "frozen_shield_pocket": frozen_shield_pocket,
        "prefreeze_selection_status": "PREFREEZE_THRESHOLD_FRONTIER_ESTABLISHED" if not frontier_df.empty else "NO_PREFREEZE_SUPPORT",
        "prefreeze_best_business_threshold": selected_threshold,
        "prefreeze_frontier_thresholds": frontier_thresholds,
        "holdout_audited_runs": int(selected_holdout_row["audited_runs"]) if selected_holdout_row else 0,
        "zero_traffic_runs": int(selected_holdout_row["zero_traffic_runs"]) if selected_holdout_row else 0,
        "key_metrics": {
            "selected_threshold_0p5_holdout": selected_holdout_row,
            "frontier_candidate_count": int(len(frontier_df)),
            "winning_alt_holdout_candidate": winning_alt_holdout,
        },
        "leakage_status": "CLEAN_PREFREEZE_SELECTION_POSTFREEZE_AUDIT_ONLY",
        "verdict": verdict,
        "refreeze_recommendation": refreeze_recommendation,
        "keep_or_kill": keep_or_kill,
        "post_freeze_runs_seen_during_selection": [],
        "v1_artifacts_used_as_decision_input": False,
    }
    return {
        "prefreeze_frontier_df": frontier_df,
        "holdout_audit_df": holdout_df,
        "summary": summary,
    }


def write_shadow_meta_v2_test_01_threshold_frontier_artifacts(
    reports_root: Path = _TRUTH_E2E_REPORTS_ROOT,
    *,
    manifest_path: Path | None = None,
) -> Dict[str, Path]:
    payload = build_shadow_meta_v2_test_01_threshold_frontier_artifacts(reports_root, manifest_path=manifest_path)
    frontier_path = reports_root / "shadow_meta_validation_line_v2_test_01_threshold_frontier_prefreeze_frontier.csv"
    holdout_path = reports_root / "shadow_meta_validation_line_v2_test_01_threshold_frontier_holdout_audit.csv"
    summary_path = reports_root / "shadow_meta_validation_line_v2_test_01_threshold_frontier_summary.json"
    payload["prefreeze_frontier_df"].to_csv(frontier_path, index=False)
    payload["holdout_audit_df"].to_csv(holdout_path, index=False)
    summary_path.write_text(json.dumps(payload["summary"], ensure_ascii=True, indent=2))
    return {
        "prefreeze_frontier_path": frontier_path,
        "holdout_audit_path": holdout_path,
        "summary_path": summary_path,
    }


def build_shadow_meta_v2_test_02_shield_counterfactual_artifacts(
    reports_root: Path = _TRUTH_E2E_REPORTS_ROOT,
    *,
    manifest_path: Path | None = None,
) -> Dict[str, Any]:
    context = _load_shadow_meta_v2_model_context(reports_root, manifest_path=manifest_path)
    threshold = 0.5
    base_stats = _threshold_surface_summary(context["val_eval"], threshold=threshold, shield_pocket=None)
    observed_pockets = sorted(str(pocket) for pocket in context["val_eval"]["pocket"].dropna().astype(str).unique().tolist())
    candidate_shields = ["NO_SHIELD"]
    for pocket in observed_pockets:
        if pocket not in candidate_shields:
            candidate_shields.append(pocket)
    if "US/20" not in candidate_shields:
        candidate_shields.append("US/20")

    prefreeze_rows: List[Dict[str, Any]] = []
    holdout_rows: List[Dict[str, Any]] = []
    for shield in candidate_shields:
        if shield == "NO_SHIELD":
            stats = base_stats
            dom = "baseline"
            rows_in_pocket = None
        else:
            pocket_mask = context["val_eval"]["pocket"].astype(str).eq(str(shield))
            rows_in_pocket = int(pocket_mask.sum())
            if rows_in_pocket <= 0:
                stats = base_stats
                dom = "no_prefreeze_support"
            else:
                stats = _threshold_surface_summary(context["val_eval"], threshold=threshold, shield_pocket=shield)
                if (
                    int(stats["correct_cata_veto"]) >= int(base_stats["correct_cata_veto"])
                    and int(stats["false_veto_total"]) < int(base_stats["false_veto_total"])
                    and float(stats["positive_exit_retention"]) > float(base_stats["positive_exit_retention"])
                    and float(stats["kept_pnl_total"]) > float(base_stats["kept_pnl_total"])
                ):
                    dom = "helpful"
                elif (
                    int(stats["false_veto_total"]) > int(base_stats["false_veto_total"])
                    or float(stats["positive_exit_retention"]) < float(base_stats["positive_exit_retention"])
                    or float(stats["kept_pnl_total"]) < float(base_stats["kept_pnl_total"])
                ):
                    dom = "harmful"
                else:
                    dom = "mixed"
        prefreeze_rows.append(
            {
                "test_name": "TEST_02_SHIELD_COUNTERFACTUAL",
                "candidate_shield": shield,
                "rows_in_prefreeze_val_pocket": rows_in_pocket,
                "prefreeze_selection_dom": dom,
                "correct_cata_veto": int(stats["correct_cata_veto"]),
                "false_veto_total": int(stats["false_veto_total"]),
                "positive_exit_retention": float(stats["positive_exit_retention"]),
                "cata_capture": float(stats["cata_capture"]),
                "kept_pnl_total": float(stats["kept_pnl_total"]),
                "veto_pnl_total": float(stats["veto_pnl_total"]),
            }
        )
        _, aggregate = _build_holdout_by_run_surface(
            context["holdout_full_df"],
            context["holdout_eval"],
            context["holdout_run_ids"],
            threshold=threshold,
            shield_pocket=None if shield == "NO_SHIELD" else shield,
            dom_field="shield_counterfactual_dom_v2",
        )
        holdout_rows.append(
            {
                "test_name": "TEST_02_SHIELD_COUNTERFACTUAL",
                "candidate_shield": shield,
                "audited_runs": int(aggregate["audited_runs"]),
                "zero_traffic_runs": int(aggregate["zero_traffic_runs"]),
                "correct_cata_veto": int(aggregate["correct_cata_veto"]),
                "false_veto_total": int(aggregate["false_veto_total"]),
                "false_veto_selected_shield_pocket": int(aggregate["false_veto_selected_shield_pocket"]),
                "positive_exit_retention": float(aggregate["positive_exit_retention"]),
                "cata_capture": float(aggregate["cata_capture"]),
                "kept_pnl_total": float(aggregate["kept_pnl_total"]),
                "veto_pnl_total": float(aggregate["veto_pnl_total"]),
            }
        )
    prefreeze_df = pd.DataFrame(prefreeze_rows)
    holdout_df = pd.DataFrame(holdout_rows)
    helpful_df = prefreeze_df.loc[prefreeze_df["prefreeze_selection_dom"] == "helpful"].copy()
    helpful_df = helpful_df.sort_values(
        ["false_veto_total", "positive_exit_retention", "kept_pnl_total", "candidate_shield"],
        ascending=[True, False, False, True],
    ).reset_index(drop=True)
    best_helpful = helpful_df.iloc[0].to_dict() if not helpful_df.empty else None
    if best_helpful is None:
        verdict = "NO_PREFREEZE_SHIELD_DOM_ESTABLISHED"
        keep_or_kill = "KILL_AS_UNSUPPORTED"
    elif str(best_helpful["candidate_shield"]) == "US/17":
        verdict = "US17_CONFIRMED"
        keep_or_kill = "KEEP_FOR_FURTHER_WORK"
    elif str(best_helpful["candidate_shield"]) == "NO_SHIELD":
        verdict = "NO_SHIELD_BETTER"
        keep_or_kill = "KILL_AS_UNSUPPORTED"
    else:
        verdict = "ALT_SHIELD_BETTER"
        keep_or_kill = "KEEP_FOR_FURTHER_WORK"
    summary = {
        "test_name": "TEST_02_SHIELD_COUNTERFACTUAL",
        "validation_line_name": _SHADOW_V2_VALIDATION_LINE_NAME,
        "source_manifest_path": context["manifest_path"],
        "prefreeze_selection_status": (
            "PREFREEZE_SHIELD_FRONT_ESTABLISHED" if not prefreeze_df.empty else "NO_PREFREEZE_SUPPORT"
        ),
        "holdout_audited_runs": int(holdout_df["audited_runs"].max()) if not holdout_df.empty else 0,
        "zero_traffic_runs": int(holdout_df["zero_traffic_runs"].max()) if not holdout_df.empty else 0,
        "key_metrics": {
            "best_helpful_prefreeze_shield": best_helpful,
            "holdout_no_shield": holdout_df.loc[holdout_df["candidate_shield"].eq("NO_SHIELD")].to_dict(orient="records"),
            "holdout_us17": holdout_df.loc[holdout_df["candidate_shield"].eq("US/17")].to_dict(orient="records"),
            "holdout_us20": holdout_df.loc[holdout_df["candidate_shield"].eq("US/20")].to_dict(orient="records"),
        },
        "leakage_status": "CLEAN_PREFREEZE_SELECTION_POSTFREEZE_AUDIT_ONLY",
        "verdict": verdict,
        "keep_or_kill": keep_or_kill,
        "post_freeze_runs_seen_during_selection": [],
        "v1_artifacts_used_as_decision_input": False,
    }
    return {
        "prefreeze_scan_df": prefreeze_df,
        "holdout_counterfactual_df": holdout_df,
        "summary": summary,
    }


