def build_shadow_meta_v2_test_03_pocket_stability_artifacts(
    reports_root: Path = _TRUTH_E2E_REPORTS_ROOT,
    *,
    manifest_path: Path | None = None,
) -> Dict[str, Any]:
    context = _load_shadow_meta_v2_model_context(reports_root, manifest_path=manifest_path)
    threshold = 0.5
    shield_pocket = "US/17"
    final_veto_mask = pd.to_numeric(context["val_eval"].get("meta_allow_score_v1"), errors="coerce") < threshold
    final_veto_mask = final_veto_mask & ~_shield_mask_from_pocket(context["val_eval"], shield_pocket)
    context_specs = {
        "pocket": context["val_eval"]["pocket"].astype(str),
        "weekday_utc": _weekday_as_string(context["val_eval"]["weekday_utc"]),
        "session": context["val_eval"].get("session", pd.Series(index=context["val_eval"].index, dtype="object")).astype(str),
        "vol_regime": context["val_eval"].get("vol_regime", pd.Series(index=context["val_eval"].index, dtype="object")).astype(str),
        "trend_regime": context["val_eval"].get("trend_regime", pd.Series(index=context["val_eval"].index, dtype="object")).astype(str),
        "session_hour_v1": context["val_eval"]["session_hour_v1"].astype(str),
        "session_hour_weekday_v1": context["val_eval"]["session_hour_weekday_v1"].astype(str),
    }
    rows: List[Dict[str, Any]] = []
    val_run_count = max(1, len(context["val_run_ids"]))
    negative_control_families = {"session_hour_v1", "session_hour_weekday_v1"}
    for family_name, family_series in context_specs.items():
        grouped = context["val_eval"].groupby(family_series.fillna("NA"), dropna=False)
        for context_value, part in grouped:
            mask = family_series.fillna("NA").eq(context_value)
            capture_mask = mask & final_veto_mask & context["val_eval"]["is_cata_v1"]
            rows.append(
                {
                    "test_name": "TEST_03_POCKET_STABILITY_AUDIT",
                    "context_family": family_name,
                    "context_value": str(context_value),
                    "is_negative_control": bool(family_name in negative_control_families),
                    "rows_total": int(mask.sum()),
                    "cata_rows_total": int((mask & context["val_eval"]["is_cata_v1"]).sum()),
                    "positive_rows_total": int((mask & context["val_eval"]["is_positive_exit_v1"]).sum()),
                    "veto_rows_after_threshold_and_shield": int((mask & final_veto_mask).sum()),
                    "captured_cata_veto_rows": int(capture_mask.sum()),
                    "false_veto_rows": int((mask & final_veto_mask & context["val_eval"]["is_positive_exit_v1"]).sum()),
                    "val_runs_present": int(context["val_eval"].loc[mask, "run_id"].astype(str).nunique()),
                    "val_runs_with_capture": int(context["val_eval"].loc[capture_mask, "run_id"].astype(str).nunique()),
                    "stable_prefreeze_rule": bool(
                        int(capture_mask.sum()) > 0
                        and int(context["val_eval"].loc[capture_mask, "run_id"].astype(str).nunique()) == val_run_count
                    ),
                }
            )
    scan_df = pd.DataFrame(rows).sort_values(
        ["stable_prefreeze_rule", "captured_cata_veto_rows", "rows_total", "context_family", "context_value"],
        ascending=[False, False, False, True, True],
    ).reset_index(drop=True)
    stable_non_negative = scan_df.loc[
        scan_df["stable_prefreeze_rule"] & ~scan_df["is_negative_control"]
    ].copy()
    stable_pocket = stable_non_negative.loc[stable_non_negative["context_family"].eq("pocket")].copy()
    stable_coarse = stable_non_negative.loc[stable_non_negative["context_family"].isin(["weekday_utc", "session", "vol_regime", "trend_regime"])].copy()
    negative_controls_stable = scan_df.loc[scan_df["stable_prefreeze_rule"] & scan_df["is_negative_control"]].copy()
    if not stable_pocket.empty:
        verdict = "STABLE_POCKET_RULE_ESTABLISHED"
        keep_or_kill = "KEEP_FOR_FURTHER_WORK"
    elif not stable_coarse.empty:
        verdict = "ONLY_COARSE_CONTEXT_STABLE"
        keep_or_kill = "KEEP_FOR_FURTHER_WORK"
    else:
        verdict = "NO_PREFREEZE_POCKET_DOM_ESTABLISHED"
        keep_or_kill = "KEEP_AS_EXPLANATORY_ONLY"
    summary = {
        "test_name": "TEST_03_POCKET_STABILITY_AUDIT",
        "validation_line_name": _SHADOW_V2_VALIDATION_LINE_NAME,
        "source_manifest_path": context["manifest_path"],
        "prefreeze_selection_status": "NO_PREFREEZE_SUPPORT" if stable_non_negative.empty else "PREFREEZE_CONTEXT_SUPPORT_FOUND",
        "holdout_audited_runs": 0,
        "zero_traffic_runs": 0,
        "key_metrics": {
            "total_captured_cata_veto_rows": int((final_veto_mask & context["val_eval"]["is_cata_v1"]).sum()),
            "stable_non_negative_rule_count": int(len(stable_non_negative)),
            "negative_controls_fail_as_expected": bool(negative_controls_stable.empty),
        },
        "leakage_status": "CLEAN_PREFREEZE_SELECTION_ONLY",
        "verdict": verdict,
        "keep_or_kill": keep_or_kill,
        "post_freeze_runs_seen_during_selection": [],
        "v1_artifacts_used_as_decision_input": False,
    }
    return {
        "context_scan_df": scan_df,
        "summary": summary,
    }


def write_shadow_meta_v2_test_03_pocket_stability_artifacts(
    reports_root: Path = _TRUTH_E2E_REPORTS_ROOT,
    *,
    manifest_path: Path | None = None,
) -> Dict[str, Path]:
    payload = build_shadow_meta_v2_test_03_pocket_stability_artifacts(reports_root, manifest_path=manifest_path)
    scan_path = reports_root / "shadow_meta_validation_line_v2_test_03_pocket_stability_scan.csv"
